From 8553d31960c136b2e58aca0c34ef58fa0b93301d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 11:19:54 +0100
Subject: [PATCH] xembed-sni-proxy: send direct clicks to the window that wants
 them

Java tray icons only select button events on a child of the embedded
window, so clicks sent straight to the embedded window were dropped and
nothing happened. Send them where a real click would end up instead.

BUG: 498824
---
 xembed-sni-proxy/sniproxy.cpp | 57 ++++++++++++++++++++++++++++++-----
 1 file changed, 49 insertions(+), 8 deletions(-)

diff --git a/xembed-sni-proxy/sniproxy.cpp b/xembed-sni-proxy/sniproxy.cpp
index aa45368c69..be49e6a1ae 100644
--- a/xembed-sni-proxy/sniproxy.cpp
+++ b/xembed-sni-proxy/sniproxy.cpp
@@ -10,6 +10,7 @@

 #include <algorithm>
 #include <span>
+#include <vector>
 #include <xcb/xcb_atom.h>
 #include <xcb/xcb_event.h>
 #include <xcb/xcb_icccm.h>
@@ -87,6 +88,43 @@ static bool checkWindowOrDescendantWantButtonEvents(xcb_window_t window)
     return std::ranges::any_of(children, &checkWindowOrDescendantWantButtonEvents);
 }

+// Find the window a real click at pos would be delivered to: the deepest viewable
+// window under it, or its closest ancestor that selected button presses
+static xcb_window_t findButtonEventWindow(xcb_window_t window, QPoint &pos)
+{
+    auto connection = qGuiApp->nativeInterface<QNativeInterface::QX11Application>()->connection();
+    std::vector<std::pair<xcb_window_t, QPoint>> path{{window, pos}};
+    while (true) {
+        const auto [current, currentPos] = path.back();
+        auto childCookie = xcb_translate_coordinates(connection, current, current, currentPos.x(), currentPos.y());
+        UniqueCPointer<xcb_translate_coordinates_reply_t> childReply(xcb_translate_coordinates_reply(connection, childCookie, nullptr));
+        if (!childReply || childReply->child == XCB_WINDOW_NONE) {
+            break;
+        }
+        auto posCookie = xcb_translate_coordinates(connection, current, childReply->child, currentPos.x(), currentPos.y());
+        UniqueCPointer<xcb_translate_coordinates_reply_t> posReply(xcb_translate_coordinates_reply(connection, posCookie, nullptr));
+        if (!posReply) {
+            break;
+        }
+        path.emplace_back(childReply->child, QPoint(posReply->dst_x, posReply->dst_y));
+    }
+    for (auto it = path.rbegin(); it != path.rend(); ++it) {
+        auto waCookie = xcb_get_window_attributes(connection, it->first);
+        UniqueCPointer<xcb_get_window_attributes_reply_t> windowAttributes(xcb_get_window_attributes_reply(connection, waCookie, nullptr));
+        if (!windowAttributes) {
+            break;
+        }
+        if (windowAttributes->all_event_masks & XCB_EVENT_MASK_BUTTON_PRESS) {
+            pos = it->second;
+            return it->first;
+        }
+        if (windowAttributes->do_not_propagate_mask & XCB_EVENT_MASK_BUTTON_PRESS) {
+            break;
+        }
+    }
+    return window;
+}
+
 SNIProxy::SNIProxy(xcb_window_t wid, QObject *parent)
     : QObject(parent)
     ,
@@ -602,24 +640,27 @@ void SNIProxy::sendClick(uint8_t mouseButton, int x, int y)
         xcb_warp_pointer(c, XCB_NONE, m_windowId, 0, 0, 0, 0, clickPoint.x(), clickPoint.y());
     }

+    QPoint eventPoint = clickPoint;
+    const xcb_window_t eventWindow = m_injectMode == Direct ? findButtonEventWindow(m_windowId, eventPoint) : m_windowId;
+
     // mouse down
     if (m_injectMode == Direct) {
         auto *event = new xcb_button_press_event_t;
         memset(event, 0x00, sizeof(xcb_button_press_event_t));
         event->response_type = XCB_BUTTON_PRESS;
-        event->event = m_windowId;
+        event->event = eventWindow;
         event->time = XCB_CURRENT_TIME;
         event->same_screen = 1;
         event->root = DefaultRootWindow(m_x11Interface->display());
         event->root_x = x;
         event->root_y = y;
-        event->event_x = static_cast<int16_t>(clickPoint.x());
-        event->event_y = static_cast<int16_t>(clickPoint.y());
+        event->event_x = static_cast<int16_t>(eventPoint.x());
+        event->event_y = static_cast<int16_t>(eventPoint.y());
         event->child = 0;
         event->state = 0;
         event->detail = mouseButton;

-        xcb_send_event(c, false, m_windowId, XCB_EVENT_MASK_BUTTON_PRESS, (char *)event);
+        xcb_send_event(c, false, eventWindow, XCB_EVENT_MASK_BUTTON_PRESS, (char *)event);
         delete event;
     } else {
         sendXTestPressed(m_x11Interface->display(), mouseButton);
@@ -630,19 +671,19 @@ void SNIProxy::sendClick(uint8_t mouseButton, int x, int y)
         auto *event = new xcb_button_release_event_t;
         memset(event, 0x00, sizeof(xcb_button_release_event_t));
         event->response_type = XCB_BUTTON_RELEASE;
-        event->event = m_windowId;
+        event->event = eventWindow;
         event->time = XCB_CURRENT_TIME;
         event->same_screen = 1;
         event->root = DefaultRootWindow(m_x11Interface->display());
         event->root_x = x;
         event->root_y = y;
-        event->event_x = static_cast<int16_t>(clickPoint.x());
-        event->event_y = static_cast<int16_t>(clickPoint.y());
+        event->event_x = static_cast<int16_t>(eventPoint.x());
+        event->event_y = static_cast<int16_t>(eventPoint.y());
         event->child = 0;
         event->state = 0;
         event->detail = mouseButton;

-        xcb_send_event(c, false, m_windowId, XCB_EVENT_MASK_BUTTON_RELEASE, (char *)event);
+        xcb_send_event(c, false, eventWindow, XCB_EVENT_MASK_BUTTON_RELEASE, (char *)event);
         delete event;
     } else {
         sendXTestReleased(m_x11Interface->display(), mouseButton);
